#!/usr/bin/env bash
set -uo pipefail

# ── start-dev-server.sh ─────────────────────────────────────────────
# Starts a web dev server in the background and waits for it to be ready.
# Auto-detects the dev command from package.json if not provided.
# Returns the PID and URL so the agent can use agent-browser.
#
# Exit codes:
#   0 = server started and ready
#   1 = server failed to start within timeout
#   2 = no dev command found
#   3 = setup error (no package.json, missing project dir, etc.)
#
# Usage:
#   ./start-dev-server.sh --project-dir /path/to/project [--command "npm run dev"] [--port 3000] [--timeout 30]
#
# Output (structured for agent parsing):
#   DEV_SERVER_PID:<pid>
#   DEV_SERVER_URL:http://localhost:<port>
#   DEV_SERVER_STATUS:READY | FAILED | TIMEOUT
#   DEV_SERVER_LOG:<path-to-log-file>
# ────────────────────────────────────────────────────────────────────

echo "[DEBUG] start-dev-server.sh invoked at $(date)"
echo "[DEBUG] args: $*"

# ── Detect OS ─────────────────────────────────────────────────────
OS_TYPE="$(uname -s)"
IS_WINDOWS=false
if [[ "$OS_TYPE" == MINGW* ]] || [[ "$OS_TYPE" == MSYS* ]] || [[ "$OS_TYPE" == CYGWIN* ]] || [[ "$OS_TYPE" == *_NT* ]]; then
  IS_WINDOWS=true
fi
echo "[DEBUG] OS_TYPE=$OS_TYPE IS_WINDOWS=$IS_WINDOWS"

PROJECT_DIR=""
COMMAND=""
PORT=""
TIMEOUT=30

# ── Parse args ─────────────────────────────────────────────────────
while [[ $# -gt 0 ]]; do
  case "$1" in
    --project-dir)  PROJECT_DIR="$2"; shift 2 ;;
    --command)      COMMAND="$2"; shift 2 ;;
    --port)         PORT="$2"; shift 2 ;;
    --timeout)      TIMEOUT="$2"; shift 2 ;;
    *) echo "DEV_SERVER_STATUS:ERROR"; echo "Unknown arg: $1"; exit 3 ;;
  esac
done

if [[ -z "$PROJECT_DIR" ]]; then
  echo "DEV_SERVER_STATUS:ERROR"
  echo "Missing --project-dir"
  exit 3
fi

echo "[DEBUG] PROJECT_DIR=$PROJECT_DIR"
echo "[DEBUG] COMMAND=$COMMAND"
echo "[DEBUG] PORT=$PORT"
echo "[DEBUG] TIMEOUT=$TIMEOUT"

cd "$PROJECT_DIR" || { echo "DEV_SERVER_STATUS:ERROR"; echo "Cannot cd to $PROJECT_DIR"; exit 3; }

echo "[DEBUG] Changed to directory: $(pwd)"

if [[ ! -f "package.json" ]]; then
  echo "DEV_SERVER_STATUS:ERROR"
  echo "No package.json found in $PROJECT_DIR"
  exit 3
fi

# ── Auto-detect dev command from package.json ──────────────────────
if [[ -z "$COMMAND" ]]; then
  # Try scripts in order of preference
  for script_name in dev start serve; do
    if node -e "const p=require('./package.json'); process.exit(p.scripts && p.scripts['$script_name'] ? 0 : 1)" 2>/dev/null; then
      COMMAND="npm run $script_name"
      break
    fi
  done
fi

if [[ -z "$COMMAND" ]]; then
  echo "DEV_SERVER_STATUS:ERROR"
  echo "No dev/start/serve script found in package.json. Available scripts:"
  node -e "const p=require('./package.json'); console.log(Object.keys(p.scripts||{}).join(', '))" 2>/dev/null || echo "(none)"
  exit 2
fi

# ── Auto-detect port if not provided ───────────────────────────────
if [[ -z "$PORT" ]]; then
  # Try to detect port from the dev command or common defaults
  DEV_SCRIPT=$(node -e "const p=require('./package.json'); const cmd='$COMMAND'.replace('npm run ',''); console.log((p.scripts||{})[cmd]||'')" 2>/dev/null)

  # Check for explicit --port flag (both --port N and --port=N formats)
  if echo "$DEV_SCRIPT" | grep -qE '\-\-port[= ]+([0-9]+)'; then
    PORT=$(echo "$DEV_SCRIPT" | grep -oE '\-\-port[= ]+([0-9]+)' | grep -oE '[0-9]+')
  elif echo "$DEV_SCRIPT" | grep -qE '\-p\s+([0-9]+)'; then
    PORT=$(echo "$DEV_SCRIPT" | grep -oE '\-p\s+([0-9]+)' | grep -oE '[0-9]+')
  # ── Framework-specific port defaults ──
  elif echo "$DEV_SCRIPT" | grep -q 'nuxt'; then
    PORT=3000
  elif echo "$DEV_SCRIPT" | grep -q 'next'; then
    PORT=3000
  elif echo "$DEV_SCRIPT" | grep -q 'remix'; then
    PORT=5173
  elif echo "$DEV_SCRIPT" | grep -q 'astro'; then
    PORT=4321
  elif echo "$DEV_SCRIPT" | grep -q 'gatsby'; then
    PORT=8000
  elif echo "$DEV_SCRIPT" | grep -q 'vite'; then
    PORT=5173
  elif echo "$DEV_SCRIPT" | grep -q 'vue-cli-service\|vue serve'; then
    PORT=8080
  elif echo "$DEV_SCRIPT" | grep -q 'angular\|ng serve'; then
    PORT=4200
  elif echo "$DEV_SCRIPT" | grep -q 'react-scripts'; then
    PORT=3000
  elif echo "$DEV_SCRIPT" | grep -q 'expo.*--web'; then
    PORT=8081
  elif echo "$DEV_SCRIPT" | grep -q 'webpack-dev-server\|webpack serve'; then
    PORT=8080
  else
    PORT=3000  # default fallback
  fi
fi

# ── Prepare log file ──────────────────────────────────────────────
LOG_DIR="$PROJECT_DIR/.locofy/dev-server-logs"
mkdir -p "$LOG_DIR"
LOG_FILE="$LOG_DIR/dev-server-$(date +%Y%m%d-%H%M%S).log"

echo "[DEBUG] Final resolved COMMAND=$COMMAND"
echo "[DEBUG] Final resolved PORT=$PORT"
echo "Starting dev server: $COMMAND (port $PORT)"
echo "Log file: $LOG_FILE"

# ── Start the dev server in background ─────────────────────────────
# CRITICAL: fully detach the process so the bash tool returns immediately.
if $IS_WINDOWS; then
  # Windows (Git Bash/MSYS2): nohup may not work reliably, use cmd /c start
  echo "[DEBUG] Launching (Windows): $COMMAND > $LOG_FILE 2>&1 &"
  $COMMAND > "$LOG_FILE" 2>&1 &
  DEV_PID=$!
else
  # macOS/Linux: nohup + disown to fully detach
  echo "[DEBUG] Launching: nohup $COMMAND > $LOG_FILE 2>&1 &"
  nohup $COMMAND > "$LOG_FILE" 2>&1 &
  DEV_PID=$!
  disown $DEV_PID 2>/dev/null || true
fi

echo "[DEBUG] Dev server launched with PID=$DEV_PID"
echo "DEV_SERVER_PID:$DEV_PID"
echo "DEV_SERVER_LOG:$LOG_FILE"

# ── Wait for server to be ready ───────────────────────────────────
ELAPSED=0
READY=false

echo "[DEBUG] Waiting for server to become ready (timeout=${TIMEOUT}s)..."
while [[ $ELAPSED -lt $TIMEOUT ]]; do
  sleep 2
  ELAPSED=$((ELAPSED + 2))

  echo "[DEBUG] Check #$((ELAPSED / 2)): elapsed=${ELAPSED}s, checking PID=$DEV_PID..."

  # Check if process is still running
  if $IS_WINDOWS; then
    # Windows: kill -0 may not work; check via /proc or tasklist
    if ! kill -0 "$DEV_PID" 2>/dev/null && ! tasklist //FI "PID eq $DEV_PID" 2>/dev/null | grep -q "$DEV_PID"; then
      echo "[DEBUG] PID $DEV_PID is no longer running!"
      echo "DEV_SERVER_STATUS:FAILED"
      echo "Dev server process exited prematurely. Last 20 lines of log:"
      tail -20 "$LOG_FILE" 2>/dev/null || echo "(no log output)"
      exit 1
    fi
  else
    if ! kill -0 "$DEV_PID" 2>/dev/null; then
      echo "[DEBUG] PID $DEV_PID is no longer running!"
      echo "DEV_SERVER_STATUS:FAILED"
      echo "Dev server process exited prematurely. Last 20 lines of log:"
      tail -20 "$LOG_FILE" 2>/dev/null || echo "(no log output)"
      exit 1
    fi
  fi

  echo "[DEBUG] PID $DEV_PID still alive. Trying http://localhost:$PORT ..."
  # Check if server is responding (curl on Unix, fallback to node on Windows)
  if command -v curl &>/dev/null; then
    if curl -sf "http://localhost:$PORT" > /dev/null 2>&1; then
      echo "[DEBUG] curl succeeded on port $PORT!"
      READY=true
      break
    fi
  else
    # Fallback: use node to make HTTP request (works on all platforms)
    if node -e "const h=require('http');h.get('http://localhost:$PORT',r=>{process.exit(r.statusCode<400?0:1)}).on('error',()=>process.exit(1))" 2>/dev/null; then
      echo "[DEBUG] node health check succeeded on port $PORT!"
      READY=true
      break
    fi
  fi
  echo "[DEBUG] Health check failed on port $PORT, checking log for port detection..."

  # Also try to detect port from log output (servers often print the URL)
  DETECTED_PORT=$(grep -oE 'localhost:([0-9]+)' "$LOG_FILE" 2>/dev/null | head -1 | grep -oE '[0-9]+$' || true)
  if [[ -n "$DETECTED_PORT" && "$DETECTED_PORT" != "$PORT" ]]; then
    PORT="$DETECTED_PORT"
    echo "[DEBUG] Detected actual port from log: $PORT"
    echo "Detected actual port from log: $PORT"
    if command -v curl &>/dev/null; then
      if curl -sf "http://localhost:$PORT" > /dev/null 2>&1; then
        echo "[DEBUG] curl succeeded on detected port $PORT!"
        READY=true
        break
      fi
    elif node -e "const h=require('http');h.get('http://localhost:$PORT',r=>{process.exit(r.statusCode<400?0:1)}).on('error',()=>process.exit(1))" 2>/dev/null; then
      echo "[DEBUG] node health check succeeded on detected port $PORT!"
      READY=true
      break
    fi
  fi

  # Print last few lines of log for debugging
  echo "[DEBUG] Last 3 lines of server log:"
  tail -3 "$LOG_FILE" 2>/dev/null || echo "(no log yet)"
done

echo "[DEBUG] Wait loop finished. READY=$READY, ELAPSED=${ELAPSED}s"

if $READY; then
  echo "DEV_SERVER_URL:http://localhost:$PORT"
  echo "DEV_SERVER_STATUS:READY"
  echo "[DEBUG] Server is ready! Exiting with status 0."
  exit 0
else
  echo "DEV_SERVER_URL:http://localhost:$PORT"
  echo "DEV_SERVER_STATUS:TIMEOUT"
  echo "Server did not respond within ${TIMEOUT}s. It may still be starting."
  echo "Last 10 lines of log:"
  tail -10 "$LOG_FILE" 2>/dev/null || echo "(no log output)"
  echo ""
  echo "The server process (PID $DEV_PID) is still running. You can:"
  if command -v curl &>/dev/null; then
    echo "  - Wait longer and check: curl -sf http://localhost:$PORT"
  else
    echo "  - Wait longer and check with node: node -e \"require('http').get('http://localhost:$PORT',r=>console.log(r.statusCode))\""
  fi
  echo "  - Check logs: cat $LOG_FILE"
  echo "  - Stop it: kill $DEV_PID"
  exit 0  # Still exit 0 — server might just be slow, agent can proceed
fi
